counterexample:
-- The queries are equivalent, so no INSERT statements create differing results under the schema constraints.
-- Example data that demonstrates equivalence:
INSERT INTO FOLLOW VALUES ('A', 'B');
INSERT INTO FOLLOW VALUES ('B', 'C');
INSERT INTO FOLLOW VALUES ('C', 'A');
-- Both queries output: ('A',1), ('B',1), ('C',1) in some order.

