-- With this data, both Q1 and Q2 return an empty result set since BUYER_ID 1 bought both products.
-- To see non-empty results, add: INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 1, 2, '2023-01-03', 1, 100);
-- Then both queries return BUYER_ID 2, still identical.

